// StaticPromptProjectorDeclines maps a BAML method name that HAS a V3 descriptor to the
// stable build-time reason no argument projector could be generated for it (a missing,
// ambiguous, or mismatched generated Go selector, or a value shape this slice does not
// project). Such a method has no native static claim: the seam declines pre-render and
// BAML serves it. Every entry is a #583 teardown blocker, not an accepted fallback.
var StaticPromptProjectorDeclines = map[string]string{}

// StaticPromptArgumentValues projects one call's ordered, already-typed arguments into
// the neutral ArgumentValue vector for method, returning ok=false when the method has no
// generated projector or the supplied arguments do not match its exact Go types. A false
// result means "no native static value binding; stay on the BAML path" — it NEVER falls
// back to reflection or to the raw argument map.
func StaticPromptArgumentValues(method string, args []any) ([]promptdescriptor.ArgumentValue, bool) {
	project, ok := StaticPromptArgumentProjectors[method]
	if !ok {
		return nil, false
	}
	return project(args)
}

// MediaParams maps function name -> param name -> media kind for parameters that are BAML media types.
var MediaParams = map[string]map[string]bamlutils.MediaKind{}

// TypeBuilder is the generated TypeBuilder type
type TypeBuilder = typebuilder.TypeBuilder

// Type is the BAML type
type Type = typebuilder.Type

// ClassPropertyBuilder is the interface for class property builders
type ClassPropertyBuilder = typebuilder.ClassPropertyBuilder

// EnumValueBuilder is the interface for enum value builders
type EnumValueBuilder = typebuilder.EnumValueBuilder

// NewTypeBuilder creates a new TypeBuilder using the BAML runtime's factory
var NewTypeBuilder = bamlclient.NewTypeBuilder

// Typed is a minimal interface for types that can return a Type
type Typed interface {
	Type() (Type, error)
}

// DynamicClassBuilder is the interface for dynamic classes
type DynamicClassBuilder interface {
	Type() (Type, error)
	AddProperty(name string, fieldType Type) (ClassPropertyBuilder, error)
}

// DynamicEnumBuilder is the interface for dynamic enums
type DynamicEnumBuilder interface {
	Type() (Type, error)
	AddValue(value string) (EnumValueBuilder, error)
}

// DynamicClassAccessor is a function that returns a DynamicClassBuilder for a dynamic class
type DynamicClassAccessor func(*TypeBuilder) (DynamicClassBuilder, error)

// DynamicEnumAccessor is a function that returns a DynamicEnumBuilder for a dynamic enum
type DynamicEnumAccessor func(*TypeBuilder) (DynamicEnumBuilder, error)

// StaticClassAccessor is a function that returns a Typed for a static class
type StaticClassAccessor func(*TypeBuilder) (Typed, error)

// StaticEnumAccessor is a function that returns a Typed for a static enum
type StaticEnumAccessor func(*TypeBuilder) (Typed, error)

// DynamicClasses maps dynamic class names to their accessor functions
var DynamicClasses = map[string]DynamicClassAccessor{}

// StaticClasses maps static class names to their accessor functions
var StaticClasses = map[string]StaticClassAccessor{"A": func(tb *TypeBuilder) (Typed, error) {
	return tb.A()
}, "B": func(tb *TypeBuilder) (Typed, error) {
	return tb.B()
}, "Loop": func(tb *TypeBuilder) (Typed, error) {
	return tb.Loop()
}, "Node": func(tb *TypeBuilder) (Typed, error) {
	return tb.Node()
}, "Palette": func(tb *TypeBuilder) (Typed, error) {
	return tb.Palette()
}, "StaticAnswer": func(tb *TypeBuilder) (Typed, error) {
	return tb.StaticAnswer()
}, "Swatch": func(tb *TypeBuilder) (Typed, error) {
	return tb.Swatch()
}}

// DynamicEnums maps dynamic enum names to their accessor functions
var DynamicEnums = map[string]DynamicEnumAccessor{}

// StaticEnums maps static enum names to their accessor functions
var StaticEnums = map[string]StaticEnumAccessor{"Color": func(tb *TypeBuilder) (Typed, error) {
	return tb.Color()
}}

// AllClasses returns all known class names (both dynamic and static)
func AllClasses() []string {
	result := make([]string, 0, len(DynamicClasses)+len(StaticClasses))
	for name := range DynamicClasses {
		result = append(result, name)
	}
	for name := range StaticClasses {
		result = append(result, name)
	}
	return result
}

// AllEnums returns all known enum names (both dynamic and static)
func AllEnums() []string {
	result := make([]string, 0, len(DynamicEnums)+len(StaticEnums))
	for name := range DynamicEnums {
		result = append(result, name)
	}
	for name := range StaticEnums {
		result = append(result, name)
	}
	return result
}

// IsDynamicClass returns true if the class exists and is dynamic
func IsDynamicClass(name string) bool {
	_, ok := DynamicClasses[name]
	return ok
}

// IsDynamicEnum returns true if the enum exists and is dynamic
func IsDynamicEnum(name string) bool {
	_, ok := DynamicEnums[name]
	return ok
}

// ClassExists returns true if a class with this name exists (dynamic or static)
func ClassExists(name string) bool {
	_, dynamic := DynamicClasses[name]
	_, static := StaticClasses[name]
	return dynamic || static
}

// EnumExists returns true if an enum with this name exists (dynamic or static)
func EnumExists(name string) bool {
	_, dynamic := DynamicEnums[name]
	_, static := StaticEnums[name]
	return dynamic || static
}

// GetClassType returns the Type for a class by name
func GetClassType(tb *TypeBuilder, name string) (Type, error) {
	if accessor, ok := DynamicClasses[name]; ok {
		builder, err := accessor(tb)
		if err != nil {
			return nil, err
		}
		return builder.Type()
	}
	if accessor, ok := StaticClasses[name]; ok {
		view, err := accessor(tb)
		if err != nil {
			return nil, err
		}
		return view.Type()
	}
	return nil, nil
}

// GetEnumType returns the Type for an enum by name
func GetEnumType(tb *TypeBuilder, name string) (Type, error) {
	if accessor, ok := DynamicEnums[name]; ok {
		builder, err := accessor(tb)
		if err != nil {
			return nil, err
		}
		return builder.Type()
	}
	if accessor, ok := StaticEnums[name]; ok {
		view, err := accessor(tb)
		if err != nil {
			return nil, err
		}
		return view.Type()
	}
	return nil, nil
}
